  const userInfo = document.querySelector('#userInfo');
  const loginForm = document.querySelector('#loginForm');
  const userInfoStyle = getComputedStyle(userInfo);
  const userInfoRect = userInfo.getBoundingClientRect();

  return {
    afterReload: {
      loginFormDisplay: getComputedStyle(loginForm).display,
      loginFormVisible: loginForm.offsetParent !== null,
      userInfoDisplay: userInfoStyle.display,
      userInfoVisibility: userInfoStyle.visibility,
      userInfoOpacity: userInfoStyle.opacity,
      userInfoRect: {
        x: userInfoRect.x,
        y: userInfoRect.y,
        width: userInfoRect.width,
        height: userInfoRect.height,
        top: userInfoRect.top,
        right: userInfoRect.right,
        bottom: userInfoRect.bottom,
        left: userInfoRect.left
      },
      displayEmail: document.querySelector('#displayEmail')?.textContent || '',
      storage: localStorage.getItem('macbot_login_status'),
      windowInnerWidth: window.innerWidth,
      documentScrollWidth: document.documentElement.scrollWidth
    }
  };
})()

